// Study settings are documented against the implemented engine, not topology assumptions.
const section=(heading,paragraphs=[],bullets=[])=>({heading,paragraphs,bullets});
const article=(id,title,summary,sections)=>({id,title,summary,tags:'study overview analysis settings '+title,sections});
export function studyTopic(path){
 const fields={'op.mode':'study-mode','op.window':'study-window','op.interpolationMethod':'study-interpolation','op.domainPolicy':'study-domain','op.fftSize':'study-spectrum','op.balancedOutput':'study-balanced-output','op.balancedInput':'study-balanced-input'};
 if(fields[path])return fields[path];
 const pair=/^op\.(inputPairs|outputPairs)\.(\d+)\.(v|i|polarity)$/.exec(path);
 if(!pair)return null;
 return pair[3]==='polarity'?'study-polarity':`study-${pair[1]==='inputPairs'?'input':'output'}-${pair[3]==='v'?'voltage':'current'}`;
}
export const STUDY_ARTICLES=[
 article('study-mode','Conversion mode: what actually changes','Determine how the tool represents input and output voltage in results and efficiency maps.',[
  section('The four modes',[],['DC/DC: Vin is the time-average input voltage; Vout is the time-average output voltage.','AC/DC: Vin is RMS; Vout is the time average.','DC/AC: Vin is the time average; Vout is RMS.','AC/AC: both Vin and Vout are RMS.']),
  section('Effect on results',['The engine computes each mapped voltage over the selected analysis window. If several voltage pairs are mapped on one side, their representative voltages are averaged. These Vin/Vout values label operating points and feed voltage filters, curves and efficiency maps. Example: a zero-mean 230 Vrms sine wave is approximately 0 V in DC mode and 230 V in AC mode over full cycles.'])]),

 article('study-window','Analysis window [s]','Select the final steady-state duration used for every operating-point file.',[
  section('Which samples are used',['Enter a positive duration in seconds. The tool takes the last requested duration ending at the final time sample. If the file is shorter, the available record is used. A start boundary between samples is linearly interpolated for every signal. Example: a file from 0 to 0.12 s with a 0.02 s window is analysed from 0.10 to 0.12 s.']),
  section('Effect on calculations',['This window sets average power, time-weighted RMS, conduction averages, switching/recovery events per second, spectra and core flux integration. Changing it can change all losses, efficiency, temperatures and reference-curve coverage. It is not a display-only zoom.']),
  section('Choosing a duration',['Use settled data and preferably whole cycles of the slowest relevant periodic behaviour. Make sure the final samples in each log and the full selected analysis window cover steady-state operation. Include enough switching cycles to represent event rates. A shorter window can miss events; a nonperiodic boundary produces spectral leakage. A longer window containing startup or drift changes the estimated operating point.'])]),
 article('study-interpolation','Interpolation method','Choose how sampled characteristics are evaluated between points and reference conditions.',[
  section("Start with the sampled curve",["A characteristic is a table of sampled points, such as current and on-state voltage. Between two samples, the tool uses a straight line: y = y1 + (x − x1) × (y2 − y1)/(x2 − x1). Example: 0.2 V at 10 A and 0.4 V at 20 A gives 0.3 V at 15 A. No polynomial fit is introduced."]),
  section("Why several reference curves are needed",["A datasheet may provide a different curve at each gate voltage, temperature or gate resistance. If your operating condition lies between references, the tool must combine those curves. An inverse query means the curve is stored as Id versus Vds but the loss calculation needs Vds for a known Id. The method controls whether this inversion happens before or after combining the curves."]),
  section("Method B — Query-First Interpolation",["First query each reference curve at the required current, inverting it if necessary. Then interpolate the returned voltage or resistance between reference conditions. Example: at Vgs = 10 V a stored curve is Id = Vds, and at Vgs = 20 V it is Id = 4 × Vds, with Id in A and Vds in V. At Id = 1 A, those references return 1 V and 0.25 V. For Vgs = 15 V, their halfway value is (1 + 0.25)/2 = 0.625 V."]),
  section("Method A — Curve-First Interpolation",["First combine the stored forward curves at the requested reference condition, then invert that combined curve if needed. In the same example, halfway between Id = Vds and Id = 4 × Vds gives Id = 2.5 × Vds. At 1 A this returns Vds = 1/2.5 = 0.4 V. This differs from 0.625 V because averaging and inversion do not generally commute. Flat or nonmonotonic combined curves are rejected when an inverse would be ambiguous. For a forward-direction query, the existing forward lookup is used."]),
  section("Method C — Distance-Weighted Interpolation (IDW²)",["First query the reference curves, then give closer reference conditions more weight. Distances are normalised to each varying dependency range; weights are proportional to 1/distance² and are normalised to sum to one. Example: resistance references of 2 mΩ at Vgs = 10 V and 12 mΩ at 20 V, queried at 12.5 V, have normalised distances 0.25 and 0.75. Their weights are 90% and 10%, giving 3 mΩ. Ordinary linear interpolation gives 4.5 mΩ. An exact reference takes precedence. This is a heuristic, not rectangular linear interpolation."]),
  section("Effect on losses",["The resulting voltage, resistance or energy feeds the enabled loss model and thermal iteration. In the inverse example, 1 A × 0.625 V gives 0.625 W, while 1 A × 0.4 V gives 0.4 W at that instant. This explains why methods can produce different losses. Curve-First (Method A) is the default for new studies; saved studies retain their interpolation selection. Out-of-domain policy controls requests outside coverage; origin and zero-floor rules belong to the characteristic."])]),
 article('study-domain','Out-of-domain policy','Control what happens when a characteristic query exceeds its reference coverage.',[
  section('Available policies',[],['Error outside reference range: reject unsupported curve/dependency queries. A required loss that cannot be computed makes the candidate incomplete.','Clamp to reference range: evaluate at the nearest supported boundary rather than extending the characteristic. This can conceal a real increase in loss, so inspect diagnostics.','Linear extrapolation: extend a boundary segment or supported dependency model beyond the reference range. The result can be physically implausible; inspect raw projections and warnings.']),
  section('Example',['For a curve containing (10 A, 0.2 V) and (20 A, 0.5 V), a 1 A request is rejected by Error, returns 0.2 V with Clamp, and extrapolates to -0.07 V with Linear extrapolation. The negative drop magnitude needs explicit review under the tool’s physical-output rules; extrapolation does not automatically approve it.']),
  section('What this changes',['This controls characteristic data coverage, not the waveform time interval. A dependency with only one reference condition remains a fixed-reference assumption. The selected interpolation method and sparse-grid support still determine which queries can be evaluated. Diagnostics retain coverage warnings.'])]),
 article('study-spectrum','Spectral samples','Set the uniform FFT grid used for frequency-dependent ESR and winding resistance.',[
  section('When this setting is used',['This setting is used for a capacitor with frequency-dependent ESR or an inductor with frequency-dependent winding resistance. The tool separates the mapped current into a DC term and harmonics, then sums harmonic RMS-current² × resistance at each harmonic frequency. With constant resistance, it uses time-domain mean-square current and does not use Spectral samples. It also does not control MOSFET switching-event detection or the core model’s separate automatic frequency estimator.']),
  section('Calculation',['The selected waveform window is linearly resampled onto N uniformly spaced points, then transformed by FFT. Available values are 256, 512, 1024, 2048 and 4096. The DC term and harmonic mean-square currents feed the frequency-dependent resistance loss model.']),
  section('Window length and frequency range',['For an actual window duration T, frequency-bin spacing is 1/T and the grid Nyquist frequency is N/(2T). With T = 1 ms and N = 1024, spacing is 1 kHz and the grid extends to 512 kHz. Raising N extends the grid range; a longer window improves bin spacing. Imported sampling still limits trustworthy bandwidth: resampling cannot recover missing high-frequency information.']),
  section('Effect on the tool',['Changing N can change spectral capacitor ESR and inductor winding losses, required reference-frequency coverage and runtime. Constant-resistance losses use time-domain mean-square current. MOSFET event counting and the core model’s separate automatic frequency estimator do not use this setting. Use whole cycles to reduce leakage and check convergence with adequate source sampling.'])]),
 ...['input','output'].map(side=>article(`study-balanced-${side}`,`Balanced three-phase ${side}: one mapped phase × 3`,`Estimate total three-phase ${side} power from one representative phase.`,[
  section('Meaning and formula',[`Balanced means the three phases have equal average real power. Enable this only when one phase represents all three, and map exactly one phase-to-neutral voltage and its matching phase current. P${side==='output'?'out':'in, mapped'} = 3 × average(vphase(t) × iphase(t) × polarity). The tool multiplies the phase’s average power; it does not reconstruct the other instantaneous phase waveforms.`,`Example: a phase averaging 1 kW represents a total of 3 kW. For sinusoidal balanced signals, total real power is 3 × Vphase,rms × Iphase,rms × cos(phi), not automatically 3 × Vrms × Irms when power factor is below one.`]),
  ...(side==='output'?[]:[section('Effect on input results',['The multiplier changes the mapped waveform input-power check in the selected-point power-flow dashboard and its discrepancy from calculated input. Reported efficiency still uses Pout/(Pout + included losses), rather than mapped input power. It does not multiply Vin, component losses or device counts.'])]),
  section('When to leave it off',['For DC or single-phase studies, leave this off and map the actual required voltage/current pairs. For an unbalanced three-phase system, map all three phase pairs with ×3 off. Never map all three phases and also enable ×3. Use phase-to-neutral voltage; pairing line-to-line voltage with a phase current does not directly give that phase’s real power.'])])),
 ...['input','output'].flatMap(side=>['voltage','current'].map(quantity=>article(`study-${side}-${quantity}`,`${side==='input'?'Input':'Output'} ${quantity} mapping`,`Choose the imported ${quantity} signal for this ${side} power pair.`,[
  section('Which signal to select',[`Select a ${quantity==='voltage'?'voltage in volts':'current in amperes'} from the imported waveform columns. Signal names must be available in every operating-point file. For AC, match phase-to-neutral voltage with the current of that same phase and align their time samples. For DC, use the voltage and current at the intended converter ${side} boundary.`,...(quantity==='voltage'?['The voltage is also used to derive the side’s representative Vin/Vout: time average for a DC side, RMS for an AC side as selected in Conversion mode.']:side==='output'?[]:['The current keeps its imported sign for the power product. A current magnitude or RMS current alone cannot preserve instantaneous real power or power factor.'])]),
  section('Effect on calculations',[side==='output'?'Output pair powers are summed and used as delivered output power for efficiency and output-power plots. These mappings do not replace individual component current/voltage mappings.':'Input pair powers are summed for the separate waveform input-power balance check. The input voltage also labels operating points. Individual component losses use their own mappings; mapped input power is not used as the denominator of the reported efficiency.']),
  section('Multiple pairs and phase selection',['Use + Phase pair to add another electrical phase or port, and − Last pair to remove the last row. With ×3 off, all complete voltage/current pairs are summed. With balanced ×3 on, use exactly one complete pair. Use Power polarity to align the signed power with the intended flow direction.'])]))),
 article('study-polarity','Power polarity: +1 or −1','Apply a sign to this pair’s instantaneous voltage × current product.',[
  section('Formula and sign',['Pair power = average(voltage(t) × current(t) × polarity). Select +1 when the imported sign convention gives positive power in the intended direction; select −1 to reverse it. This changes only the pair’s power sign, not the stored waveforms or component currents.']),
  section('Output and input use',['For the output mapping, positive power means energy leaves the converter through the selected output port. The sum of the output pairs must be positive to calculate efficiency. If the voltage and current measurement directions make that flow negative, use −1 for the affected pair. When analysing reverse power flow, map the port now receiving delivered converter power as the study output; for example, in a bidirectional DC/DC converter feeding the HV bus from the LV bus, the HV port is the output. Input polarity only changes the separate input-power balance check. Changing polarity does not swap ports or component mappings.']),
  section('Example',['A DC pair with 400 V and -10 A gives -4 kW at +1 and +4 kW at −1. For AC, the sign multiplies the average instantaneous real power; it does not remove reactive power or substitute an apparent-power calculation.'])])
];
